//! Bounded model of the output writes in SporeApp.exe E59B40, q493.
//!
//! Inputs are supplied observations, not candidates generated by this module.
//! The model assumes non-aliasing candidate and output data and IEEE-754 binary32
//! comparison with denormals enabled and floating exceptions masked. It does not
//! reproduce COMISS exceptions, MXCSR flags/modes, memory aliasing, geometry,
//! candidate generation, or event dispatch. Names are descriptive, not types
//! established from original source. The 32-bit payload words are copied intact.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ContactOutput {
    pub actor_ids: [u32; 2],        // +00, +04
    pub selector: i32,              // +08, signed CMP/JG
    pub feature_indices: [u32; 2],  // +0c, +10
    pub depth_bits: u32,            // +14, binary32
    pub point_words: [u32; 3],      // +18..+20
    pub normal_words: [u32; 3],     // +24..+2c
}

/// Reports the two native write paths independently; both can occur in one call.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ArbitrationWrites {
    pub priority_or_depth: bool,
    pub player_selector_eight: bool,
}

// COMISS candidate, stored followed by JBE skips the normal write for less,
// equal, or unordered. Compare bits to avoid depending on host FP modes and to
// retain NaN payloads. Signed zeros are equal; all NaNs are unordered.
fn ordered_binary32_greater(candidate: u32, stored: u32) -> bool {
    fn is_nan(bits: u32) -> bool {
        bits & 0x7f80_0000 == 0x7f80_0000 && bits & 0x007f_ffff != 0
    }
    if is_nan(candidate) || is_nan(stored) {
        return false;
    }
    if candidate & 0x7fff_ffff == 0 && stored & 0x7fff_ffff == 0 {
        return false;
    }
    let candidate_negative = candidate >> 31 != 0;
    let stored_negative = stored >> 31 != 0;
    if candidate_negative != stored_negative {
        return !candidate_negative;
    }
    if candidate_negative {
        candidate < stored
    } else {
        candidate > stored
    }
}

/// Applies one supplied candidate to the supplied current output.
/// `current_player_id` is the native global value at its read after any first
/// output write, when the selector-eight path reaches that read.
pub fn submit_contact_candidate(
    output: &mut ContactOutput,
    candidate: ContactOutput,
    current_player_id: u32,
) -> ArbitrationWrites {
    let priority_or_depth = candidate.selector > output.selector
        || (candidate.selector == output.selector
            && ordered_binary32_greater(candidate.depth_bits, output.depth_bits));
    if priority_or_depth {
        *output = candidate;
    }
    // This uses the selector after the first write, as in E59BAE.
    let player_selector_eight = candidate.selector == output.selector
        && candidate.selector == 8
        && candidate.actor_ids[0] == current_player_id;
    if player_selector_eight {
        *output = candidate;
    }
    ArbitrationWrites { priority_or_depth, player_selector_eight }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn contact(selector: i32, depth_bits: u32, id: u32) -> ContactOutput {
        ContactOutput {
            actor_ids: [id, id.wrapping_add(1)],
            selector,
            feature_indices: [id.wrapping_add(2), id.wrapping_add(3)],
            depth_bits,
            point_words: [id.wrapping_add(4), id.wrapping_add(5), 0x7fa0_1234],
            normal_words: [0x8000_0000, id.wrapping_add(6), id.wrapping_add(7)],
        }
    }

    #[test]
    fn signed_priority_and_all_payload_words() {
        let mut output = contact(-1, 100.0f32.to_bits(), 1);
        let candidate = contact(0, 0x7fc0_1234, 42);
        let writes = submit_contact_candidate(&mut output, candidate, 99);
        assert_eq!(writes, ArbitrationWrites { priority_or_depth: true, player_selector_eight: false });
        assert_eq!(output, candidate);
        let lower = contact(i32::MIN, f32::INFINITY.to_bits(), 2);
        assert!(!submit_contact_candidate(&mut output, lower, 99).priority_or_depth);
        assert_eq!(output, candidate);
    }

    #[test]
    fn ordered_depth_and_ieee_special_values() {
        let cases = [
            (2.0f32.to_bits(), 1.0f32.to_bits(), true),
            (1.0f32.to_bits(), 1.0f32.to_bits(), false),
            ((-2.0f32).to_bits(), (-1.0f32).to_bits(), false),
            ((-1.0f32).to_bits(), (-2.0f32).to_bits(), true),
            (0, 0x8000_0000, false),
            (0x8000_0000, 0, false),
            (1, 0, true),
            (0x8000_0000, 0x8000_0001, true),
            (f32::INFINITY.to_bits(), f32::MAX.to_bits(), true),
            (f32::NEG_INFINITY.to_bits(), (-1.0f32).to_bits(), false),
            (0x7fc0_0001, 1.0f32.to_bits(), false),
            (1.0f32.to_bits(), 0xff80_0001, false),
            (0x7f80_0001, 0x7fc0_0001, false),
        ];
        for (candidate, stored, expected) in cases {
            let mut output = contact(4, stored, 1);
            let old = output;
            let incoming = contact(4, candidate, 2);
            let result = submit_contact_candidate(&mut output, incoming, 99);
            assert_eq!(result.priority_or_depth, expected, "candidate={candidate:08x}, stored={stored:08x}");
            assert_eq!(output, if expected { incoming } else { old });
        }
    }

    #[test]
    fn selector_eight_override_checks_updated_selector_and_first_actor() {
        let player = contact(8, 0x7fc0_1234, 42);
        let mut output = contact(8, 100.0f32.to_bits(), 3);
        assert_eq!(submit_contact_candidate(&mut output, player, 42), ArbitrationWrites {
            priority_or_depth: false, player_selector_eight: true,
        });
        assert_eq!(output, player);
        output = contact(9, 0, 3);
        assert_eq!(submit_contact_candidate(&mut output, player, 42), ArbitrationWrites {
            priority_or_depth: false, player_selector_eight: false,
        });
        output = contact(7, 0, 3);
        assert_eq!(submit_contact_candidate(&mut output, player, 42), ArbitrationWrites {
            priority_or_depth: true, player_selector_eight: true,
        });
        output = contact(8, 100.0f32.to_bits(), 3);
        assert_eq!(submit_contact_candidate(&mut output, player, player.actor_ids[1]), ArbitrationWrites {
            priority_or_depth: false, player_selector_eight: false,
        });
    }

    #[test]
    fn ordering_matters_for_ties_and_player_override() {
        let a = contact(8, 10.0f32.to_bits(), 1);
        let b = contact(8, 10.0f32.to_bits(), 2);
        let mut first_a = contact(0, 0, 0);
        submit_contact_candidate(&mut first_a, a, 99);
        submit_contact_candidate(&mut first_a, b, 99);
        let mut first_b = contact(0, 0, 0);
        submit_contact_candidate(&mut first_b, b, 99);
        submit_contact_candidate(&mut first_b, a, 99);
        assert_eq!(first_a, a);
        assert_eq!(first_b, b);
        submit_contact_candidate(&mut first_b, a, 1);
        assert_eq!(first_b, a);
    }
}
